// Game art: where the extracted Character-screen assets live and how the game puts them together.
// No DOM. File sizes come from assets/ui/manifest.json and positions from assets/ui/layout/*.json,
// both generated by tools/build_ui_assets.py. Every other value here is documented, with its
// source in the game files, in docs/game-assets.md.

const BASE = "assets/ui";
const LAYOUTS = ["screen", "tree-panel", "tree-node", "tab", "tooltip", "legend-button",
  "mutagen-panel", "mutagen-slots", "mutagen-socket", "mutagen-diamond", "pip"];

// Vector files have no size in the manifest. `origin` is where the piece's own (0, 0) sits inside
// the file: place the file at -origin and the piece lands where its layout matrix puts it.
const VECTORS = [
  [/^(node|slots)\/lock\.svg$/, { size: [56.15, 54.5] }],
  [/^slots\/frame\.svg$/, { size: [81.1, 77.85] }],
  [/^slots\/selected\.svg$/, { size: [73.4, 69.15], origin: [36.7, 34.55] }],
  [/^mutagens\/diamond-frame\.svg$/, { size: [89.65, 86.45], origin: [13.6, 11.4] }],
  [/^mutagens\/connectors\/corner-/, { size: [93.2, 32.95], origin: [2.5, 10.5] }],
  [/^mutagens\/connectors\/line-/, { size: [11.4, 30.4], origin: [5.65, 6.1] }],
  [/^legend\/key\.svg$/, { size: [50.85, 50.8] }]
];

export const artUrl = file => `${BASE}/${file}`;

// The dropdown arrow of the game's category lists (IconDropDownListItem.mcOpenedState, the alchemy
// panel's DropDownArrows): game art cut to a one-colour glyph (tools/asset-recipe.json,
// icons/dropdown-arrow.png, 18 x 14 px), pointing down. Drawn 11 u wide with its centroid (9, 4.68
// px) at (0, 0), so on a disc centred there it is centred and turns on that. It is a rect in the
// fill colour masked by the art (an SVG mask, so it is tinted and drawn in the same pass). Used by
// the side panels' toggles (ui/sidePanel.js) and a skill's touch buttons (gamePieces.stepButton).
const ARROW_W = 11, ARROW_H = ARROW_W * 14 / 18, ARROW_TOP = -ARROW_W * 4.68 / 18;
const arrowBox = `x="${-ARROW_W / 2}" y="${ARROW_TOP}" width="${ARROW_W}" height="${ARROW_H}"`;
/** The arrow's art as an SVG mask with id `id`, for dropdownArrow. */
export const dropdownArrowMask = id =>
  `<mask id="${id}"><image href="${artUrl("icons/dropdown-arrow.png")}" ${arrowBox} preserveAspectRatio="none"/></mask>`;
/** The arrow, masked by the dropdownArrowMask with id `maskId`, filled with the current fill. */
export const dropdownArrow = maskId => `<rect ${arrowBox} mask="url(#${maskId})"/>`;

// Game colour label, skill icon folder and stat icon (STAT_GLYPHS) per planner tree. The stat icons
// are the ones the character stats popup (CharacterStatsPopup.ws) gives its categories of that
// colour: steel attack (red), sign intensity (blue), toxicity (green), additional (brown).
export const TREE_ART = {
  combat: { color: "red", skills: "sword", stat: "attack-steel" },
  signs: { color: "blue", skills: "signs", stat: "spell-power" },
  alchemy: { color: "green", skills: "alchemy", stat: "toxicity" },
  general: { color: "yellow", skills: "perks", stat: "additional" }
};
// Stat icon of the character stats popup (panel_inventory, FullStatsItemRef): stats/shield.png at
// `shield`, then the glyph (mcStatIcons) at alpha 0.6 with its sprite at `glyph`. Each glyph frame
// draws its file at its own offset from there: STAT_GLYPHS, as [x, y, w, h]. The game draws the
// glyph at alpha 0.6 on its dark rows; on the bright colour bars that washes out, so it is 0.9 here
// (by eye). The shield art is black at about 12% alpha, which vanishes on the bars too, so its alpha
// is multiplied by `shieldBoost` (sidePanel.statIconFilters, by eye).
export const STAT_ICON = { shield: [16.5, 3.25, 64, 64], glyph: [49.25, 33.5], alpha: 0.9, shieldBoost: 5 };
export const STAT_GLYPHS = {
  "attack-steel": [-32, -31.95, 64, 64],
  "spell-power": [-33.15, -36.55, 64, 64],
  toxicity: [-33.2, -34.15, 64, 64],
  additional: [-32.1, -17, 64, 32]
};
// The Character screen is laid out on a 1920x1080 screen; layout/screen.json uses these units.
export const SCREEN = { w: 1920, h: 1080 };
// Backdrop fill under everything (panel_common, MC_IMG_Background_Assets).
export const BACKDROP_FILL = "#040404";
// mcStateDropTarget's outline (sprite 509 > 508 at alpha 0.6 > shape 507, a 1px stroke).
export const DROP_TARGET = { color: "#ffcc00", alpha: 0.6 };
// Hover glow on a slot's icon (SlotBase OVER_GLOW_*: GlowFilter 15990722, blur 15, strength 0.75, high
// quality). Three box-blur passes of 15px come close to a Gaussian of sigma 7.5. Inventory mutagens fill
// their whole cell with a bright round icon, so the game's blur spreads far past it: they use a smaller one (by eye).
export const OVER_GLOW = { color: "#f3ffc2", strength: 0.75, sigma: { skill: 7.5, item: 3 } };
